if (typeof module !== "undefined" && module.exports) module.exports = { shelter, webSource, es: { shelter: shelterEs }, esSource };

if (require.main === module) {
  // Same rule as scripts/verify-scripture.js: verbatim, or verbatim once a
  // closing period the source does not have is dropped.
  const MODERNIZE = t => t.replace(/Yahweh/g, "the LORD").replace(/utility belt/g, "belt");
  const norm = t => t.replace(/\s+/g, " ").trim().toLowerCase();
  let fail = 0;
  shelter.days.forEach(([title, ref, verse], i) => {
    const source = webSource[ref];
    const hay = source && norm(MODERNIZE(source));
    const needle = norm(verse);
    const status = !source ? "no-source"
      : hay.includes(needle) ? "verbatim"
      : hay.includes(needle.replace(/[.?!]$/, "")) ? "punctuation"
      : "not-in-source";
    if (status === "no-source" || status === "not-in-source") fail++;
    console.log(`${status.padEnd(13)} day ${i + 1} ${title} (${ref})`);
  });
  console.log(fail ? `\n${fail} excerpt(s) not drawn from the WEB` : `\nAll ${shelter.days.length} excerpts drawn from the WEB`);

  // Spanish: the reference is the English one with the book named as
  // scripts/es-books.json names it, and the verse a contiguous substring of
  // the Reina-Valera 1909 with no substitutions.
  const ES_BOOKS = require("../scripts/es-books.json");
  const esRefFor = ref => ref.replace(/^(.*?)(\s+\d+:.*)$/, (_, b, rest) => (ES_BOOKS[b] || b) + rest);
  let esFail = 0;
  if (shelterEs.days.length !== shelter.days.length) { console.log(`\nSpanish has ${shelterEs.days.length} days, English ${shelter.days.length}`); esFail++; }
  shelterEs.days.forEach((d, i) => {
    const [, enRef] = shelter.days[i] || [];
    const source = esSource[enRef];
    const needle = norm(d[2]);
    const status = d.length !== 7 || d.some(f => typeof f !== "string" || !f.trim()) ? "fields"
      : d[1] !== esRefFor(enRef) ? "reference"
      : !source ? "no-source"
      : norm(source).includes(needle) ? "verbatim"
      : norm(source).includes(needle.replace(/[.?!]$/, "")) ? "punctuation"
      : "not-in-source";
    if (!["verbatim", "punctuation"].includes(status)) esFail++;
    console.log(`${status.padEnd(13)} día ${i + 1} ${d[0]} (${d[1]})`);
  });
  console.log(esFail ? `\n${esFail} Spanish day(s) failing` : `\nAll ${shelterEs.days.length} Spanish excerpts drawn from the Reina-Valera 1909`);
  process.exit(fail || esFail ? 1 : 0);
}
